      "arFull": "اَلَّذِیْنَ یَحْمِلُوْنَ الْعَرْشَ وَمَنْ حَوْلَهٗ یُسَبِّحُوْنَ بِحَمْدِ رَبِّهِمْ وَیُؤْمِنُوْنَ بِهٖ وَیَسْتَغْفِرُوْنَ لِلَّذِیْنَ اٰمَنُوْا ۚ رَبَّنَا وَسِعْتَ كُلَّ شَیْءٍ رَّحْمَةً وَّعِلْمًا فَاغْفِرْ لِلَّذِیْنَ تَابُوْا وَاتَّبَعُوْا سَبِیْلَكَ وَقِهِمْ عَذَابَ الْجَحِیْمِ ۟",
      "ur": "عرش کے اٹھانے والے اور اسکے آس پاس کے (فرشتے) اپنے رب کی تسبیح حمد کے ساتھ ساتھ کرتے ہیں اور اس پر ایمان رکھتے ہیں اور ایمان والوں کے لیے استفغار کرتے ہیں، کہتے ہیں کہ اے ہمارے پروردگار! تو نے ہر چیز کو اپنی بخشش اور علم سے گھیر رکھا ہے، پس تو انہیں بخش دے جو توبہ کریں اور تیری راه کی پیروی کریں اور تو انہیں دوزخ کے عذاب سے بھی بچا لے.[1]",
      "en": "Those [angels] who carry the Throne and those around it exalt [Allāh] with praise of their Lord and believe in Him and ask forgiveness for those who have believed, [saying], \"Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who have repented and followed Your way and protect them from the punishment of Hellfire.",
      "footnotesUr": "[1] اس میں ملائکہ مقربین کے ایک خاص گروہ کا تذکرہ اور وہ جو کچھ کرتے ہیں، اس کی وضاحت ہے، یہ گروہ ہے ان فرشتوں کا جو عرش کو اٹھائے ہوئےہیں اور وہ جو عرش کے اردگرد ہیں۔ ان کا ایک کام یہ ہے کہ یہ اللہ کی تسبیح و تحمید کرتے ہیں، یعنی نقائص سے اس کی تنزیہ، کمالات اور خوبیوں کا اس کے لیے اثبات اور اس کے سامنے عجز و تذلل یعنی (ایمان) کا اظہار کرتے ہیں۔ دوسرا کام ا ن کا یہ ہے کہ یہ اہل ایمان کے لیے مغفرت کی دعا کرتے ہیں، کہا جاتا ہےکہ عرش کو اٹھانے والے فرشتے چار ہیں، مگر قیامت والے دن ان کی تعداد آٹھ ہو گی۔ (ابن کثیر)۔",
      "footnotesEn": null,
