      "number": 13,
      "arFull": "هُوَ الَّذِیْ یُرِیْكُمْ اٰیٰتِهٖ وَیُنَزِّلُ لَكُمْ مِّنَ السَّمَآءِ رِزْقًا ؕ وَمَا یَتَذَكَّرُ اِلَّا مَنْ یُّنِیْبُ ۟",
