      "arFull": "یَوْمَ هُمْ بٰرِزُوْنَ ۚ۬ لَا یَخْفٰی عَلَی اللّٰهِ مِنْهُمْ شَیْءٌ ؕ لِمَنِ الْمُلْكُ الْیَوْمَ ؕ لِلّٰهِ الْوَاحِدِ الْقَهَّارِ ۟",
      "ur": "جس دن سب لوگ ﻇاہر ہو جائیں گے[1] ، ان کی کوئی چیز اللہ سے پوشیده نہ رہے گی۔ آج کس کی بادشاہی ہے[2]؟ فقط اللہ واحد و قہار کی.[3]",
      "en": "The Day they come forth nothing concerning them will be concealed from Allāh. To whom belongs [all] sovereignty this Day? To Allāh, the One, the Prevailing.[1365]",
      "footnotesUr": "[1] یعنی زندہ ہوکر قبروں سے باہر نکل کھڑے ہوں گے۔\n[2] یہ قیامت والے دن اللہ تعالیٰ پوچھے گا، جب سارے انسان اس کے سامنے میدان محشر میں جمع ہوں گے، اللہ تعالیٰ زمین کو اپنی مٹھی میں اور آسمان کو اپنے دائیں ہاتھ میں لپیٹ لے گا، اور کہے گا میں بادشاہ ہوں، زمین کے بادشاہ کہاں ہیں؟ (صحیح بخاری، سورۂ زمر)۔\n[3] جب کوئی نہیں بولے گا تو یہ جواب اللہ تعالیٰ خود ہی دے گا۔ بعض کہتے ہیں کہ اللہ تعالیٰ کے حکم سے ایک فرشتہ منادی کرے گا، جس کے ساتھ ہی تمام کافر اور مسلمان بیک آواز یہی جواب دیں گے۔ (فتح القدیر)۔",
      "footnotesEn": "[1365] Refer to footnotes in 12:39.",
