      "arFull": "وَقَالَ الَّذِیْۤ اٰمَنَ یٰقَوْمِ اِنِّیْۤ اَخَافُ عَلَیْكُمْ مِّثْلَ یَوْمِ الْاَحْزَابِ ۟ۙ",
