      "number": 44,
      "arFull": "فَسَتَذْكُرُوْنَ مَاۤ اَقُوْلُ لَكُمْ ؕ وَاُفَوِّضُ اَمْرِیْۤ اِلَی اللّٰهِ ؕ اِنَّ اللّٰهَ بَصِیْرٌ بِالْعِبَادِ ۟",
      "ur": "پس آگے چل کر تم میری باتوں کو یاد کرو گے[1] میں اپنا معاملہ اللہ کے سپرد کرتا ہوں[2]، یقیناً اللہ تعالیٰ بندوں کا نگراں ہے.[3]",
      "en": "And you will remember what I [now] say to you, and I entrust my affair to Allāh. Indeed, Allāh is Seeing of [His] servants.\"",
      "footnotesUr": "[1] عنقریب وہ وقت آئے گا جب میری باتوں کی صداقت، اور جن باتوں سےروکتا تھا،ان کی شناعت تم پر واضح ہو جائےگی، پھر تم ندامت کا اظہار کرو گے، مگر وہ وقت ایسا ہوگا کہ ندامت بھی کوئی فائدہ نہیں دےگی۔\n[2] یعنی اسی پر بھروسہ کرتا اور اسی سے ہر وقت استعانت کرتا ہوں اور تم سے بیزاری اور قطع تعلق کا اعلان کرتاہوں۔\n[3] وہ انہیں دیکھ رہا ہے۔ پس وہ مستحق ہدایت کو ہدایت سے نوازتا اور ضلالت کا استحقاق رکھنے والے کو ضلالت سے ہمکنار کرتا ہے۔ ان امور میں جو حکمتیں ہیں، ان کو وہی خوب جانتا ہے۔",
