      "arFull": "وَقَالَ الَّذِیْنَ فِی النَّارِ لِخَزَنَةِ جَهَنَّمَ ادْعُوْا رَبَّكُمْ یُخَفِّفْ عَنَّا یَوْمًا مِّنَ الْعَذَابِ ۟",
