      "number": 82,
      "arFull": "اَفَلَمْ یَسِیْرُوْا فِی الْاَرْضِ فَیَنْظُرُوْا كَیْفَ كَانَ عَاقِبَةُ الَّذِیْنَ مِنْ قَبْلِهِمْ ؕ كَانُوْۤا اَكْثَرَ مِنْهُمْ وَاَشَدَّ قُوَّةً وَّاٰثَارًا فِی الْاَرْضِ فَمَاۤ اَغْنٰی عَنْهُمْ مَّا كَانُوْا یَكْسِبُوْنَ ۟",
      "ur": "کیا انہوں نے زمین میں چل پھر کر اپنے سے پہلوں کا انجام نہیں دیکھا[1] ؟ جو ان سے تعداد میں زیاده تھے قوت میں سخت اور زمین میں بہت ساری یادگاریں چھوڑی تھیں[2]، ان کے کیے کاموں نے انہیں کچھ بھی فائده نہیں پہنچایا.[3]",
      "en": "Have they not traveled through the land and observed how was the end of those before them? They were more numerous than themselves and greater in strength and in impression on the land, but they were not availed by what they used to earn.",
      "footnotesUr": "[1] یعنی جن قوموں نے اللہ کی نافرمانی اور اس کے رسولوں کی تکذیب کی، یہ ان کی بستیوں کے آثار اور کھنڈرات تو دیکھیں جو ان کے علاقوں میں ہی ہیں کہ ان کا کیا انجام ہوا؟\n[2] یعنی عمارتوں، کارخانوں اور کھیتیوں کی شکل میں، ان کے کھنڈرات واضح کرتے ہیں کہ وہ کاریگری کےمیدان میں بھی تم سے بڑھ کر تھے۔\n[3] فَمَا أَغْنَى میں مَا استفہامیہ بھی ہو سکتا ہے اور نافیہ بھی۔ نافیہ کامﻔہوم تو ترجمے سے واضح ہے۔ کہ استفہامیہ کی رو سے مطلب ہوگا۔ ان کوکیا فائدہ پہنچایا؟ مطلب وہی ہے کہ ان کی کمائی ان کے کچھ کام نہیں آئی۔",
