      "arFull": "فَلَمَّا جَآءَتْهُمْ رُسُلُهُمْ بِالْبَیِّنٰتِ فَرِحُوْا بِمَا عِنْدَهُمْ مِّنَ الْعِلْمِ وَحَاقَ بِهِمْ مَّا كَانُوْا بِهٖ یَسْتَهْزِءُوْنَ ۟",
